import { I } from '@angular/cdk/keycodes';
import { CommonModule } from '@angular/common';
import { afterNextRender, afterRender, AfterRenderPhase, ChangeDetectorRef, Component, ElementRef, EventEmitter, Input, Output, SimpleChanges, ViewChild } from '@angular/core';
import { MatTooltipModule } from '@angular/material/tooltip';
@Component({
  selector: 'app-tabletrunc',
  standalone: true,
  imports: [CommonModule, MatTooltipModule
  ],
  templateUrl: './tabletrunc.component.html'
})
export class TabletruncComponent {
  @Input() value: string;
  @Input() noPadding: boolean = false;
  @Input() addcls: string = '';
  isTruncated = false;
  @Input() callcatched = false;


  @ViewChild('flname', { static: false }) flname!: ElementRef;
  constructor() {
    afterNextRender(() => {
      this.checkTruncate();
    }, { phase: AfterRenderPhase.MixedReadWrite });
  }

  ngAfterViewInit() {
    // console.log('after view rendered', 'currunt time in seconds', new Date().getTime());
  }


  ngOnChanges(changes: SimpleChanges) {
    if (changes['callcatched']) {
      this.checkTruncate();
    }
  }




  checkTruncate() {
    if (!this.flname) return;
    const elm = this.flname.nativeElement;
    const clone = elm.cloneNode(true) as HTMLElement;
    clone.style.width = 'fit-content';
    clone.style.position = 'absolute';
    clone.style.visibility = 'hidden';
    clone.style.whiteSpace = 'nowrap';
    elm.parentElement.appendChild(clone);
    this.isTruncated = clone.clientWidth > elm.parentElement.clientWidth;
    clone.remove();
  }




}
